('prod-bread-britannia-wheat', 'c1000000-0000-0000-0000-000000000003', 'Britannia 100% Whole Wheat Bread 400g', 'Britannia', 'Nutritious whole wheat loaf baked with goodness of pure wheat grains. 100% Maida Free.', 50, 55, 9, '400g', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=600&auto=format&fit=crop&q=80', 'Aisle 6', 'Bakery Section, Aisle 6 - Rack 2', '{"calories":242,"protein":"8.3g","fat":"1.6g","carbs":"46g","serving_size":"100g"}'::jsonb, ARRAY['Whole Wheat', 'Brown Bread', 'No Maida']::text[], 4.7, 1100, FALSE),
('prod-pasta-barilla-penne', 'c1000000-0000-0000-0000-000000000004', 'Barilla Penne Rigate Italian Pasta 500g', 'Barilla', 'Authentic imported Italian durum wheat semolina pasta. Holds sauce perfectly al dente.', 220, 245, 10, '500g', 'https://images.unsplash.com/photo-1621996346565-e3d5d6281096?w=600&auto=format&fit=crop&q=80', 'Aisle 2', 'Pasta & Grains, Aisle 2 - Shelf B1', '{"calories":359,"protein":"12.5g","fat":"2.0g","carbs":"71g","serving_size":"100g"}'::jsonb, ARRAY['Italian Pasta', 'Penne', 'Durum Wheat', 'Al Dente']::text[], 4.9, 2150, FALSE),
('prod-pasta-delmonte-fusilli', 'c1000000-0000-0000-0000-000000000004', 'Del Monte Durum Wheat Fusilli Pasta 500g', 'Del Monte', 'Premium spiraled pasta made with 100% durum wheat semolina. Excellent source of dietary protein.', 145, 160, 9, '500g', 'https://images.unsplash.com/photo-1551462147-37885acc36f1?w=600&auto=format&fit=crop&q=80', 'Aisle 2', 'Pasta & Grains, Aisle 2 - Shelf B2', '{"calories":350,"protein":"12g","fat":"1.5g","carbs":"72g","serving_size":"100g"}'::jsonb, ARRAY['Fusilli', 'Spiral Pasta', 'Durum Wheat']::text[], 4.7, 940, FALSE),
('prod-spinach', 'c1000000-0000-0000-0000-000000000002', 'Fresh Organic Baby Spinach (Palak) 250g', 'Farm Fresh Organic', 'Crisp, washed organic tender baby spinach leaves. Rich in iron, vitamins A & C, and folate.', 35, 40, 12, '250g', 'https://images.unsplash.com/photo-1576045057995-568f588f82fb?w=600&auto=format&fit=crop&q=80', 'Aisle 1', 'Produce Bin 5, Aisle 1 (Chilled Greens)', '{"calories":23,"protein":"2.9g","fat":"0.4g","carbs":"3.6g","serving_size":"100g"}'::jsonb, ARRAY['Spinach', 'Palak', 'Organic', 'Iron Rich', 'Green Leafy']::text[], 4.8, 670, TRUE),
('prod-broccoli', 'c1000000-0000-0000-0000-000000000002', 'Fresh Farm Broccoli Florets 250g', 'Farm Fresh Organic', 'Nutrient-dense dark green broccoli florets. Superfood loaded with dietary fiber, antioxidants, and vitamins.', 60, 70, 14, '250g', 'https://images.unsplash.com/photo-1459411621453-7b03977f4bfc?w=600&auto=format&fit=crop&q=80', 'Aisle 1', 'Produce Bin 6, Aisle 1 (Fresh Vegetables)', '{"calories":34,"protein":"2.8g","fat":"0.4g","carbs":"6.6g","serving_size":"100g"}'::jsonb, ARRAY['Broccoli', 'Weight Loss', 'High Fiber', 'Antioxidants', 'Superfood']::text[], 4.9, 820, TRUE),
('prod-carrots', 'c1000000-0000-0000-0000-000000000002', 'Premium Crisp Orange Carrots 500g', 'Farm Fresh Organic', 'Sweet and crunchy farm-fresh carrots. Loaded with beta-carotene, Vitamin A, and eye-health nutrients.', 45, 50, 10, '500g', 'https://images.unsplash.com/photo-1598170845058-32b9d6a5da37?w=600&auto=format&fit=crop&q=80', 'Aisle 1', 'Produce Bin 7, Aisle 1 (Root Vegetables)', '{"calories":41,"protein":"0.9g","fat":"0.2g","carbs":"9.6g","serving_size":"100g"}'::jsonb, ARRAY['Carrots', 'Vitamin A', 'Beta Carotene', 'Healthy Snacking']::text[], 4.7, 530, TRUE),
('prod-capsicum', 'c1000000-0000-0000-0000-000000000002', 'Fresh Green Bell Pepper (Capsicum) 500g', 'Farm Fresh Produce', 'Crisp and juicy green bell peppers. Ideal for stir-fries, curries, pizzas, and pasta dishes.', 55, 65, 15, '500g', 'https://images.unsplash.com/photo-1563565375-f3fdfdbefa83?w=600&auto=format&fit=crop&q=80', 'Aisle 1', 'Produce Bin 8, Aisle 1 (Fresh Vegetables)', '{"calories":20,"protein":"0.9g","fat":"0.2g","carbs":"4.6g","serving_size":"100g"}'::jsonb, ARRAY['Capsicum', 'Bell Pepper', 'Stir Fry', 'Vitamin C']::text[], 4.6, 490, FALSE),
('prod-potatoes', 'c1000000-0000-0000-0000-000000000002', 'Farm Fresh Golden Potatoes 1kg', 'Farm Fresh Produce', 'Smooth golden farm potatoes, perfect for boiling, roasting, curries, and mashed potatoes.', 35, 40, 12, '1kg', 'https://images.unsplash.com/photo-1518977676601-b53f82aba655?w=600&auto=format&fit=crop&q=80', 'Aisle 1', 'Produce Bin 3, Aisle 1 (Root Vegetables)', '{"calories":77,"protein":"2.0g","fat":"0.1g","carbs":"17g","serving_size":"100g"}'::jsonb, ARRAY['Potatoes', 'Aloo', 'Kitchen Staple']::text[], 4.8, 1200, FALSE),
('prod-nandini-milk', 'c1000000-0000-0000-0000-000000000001', 'Nandini Fresh Toned Milk 500ml', 'Nandini', 'Pure, fresh pasteurized toned milk from Karnataka Milk Federation. 3.0% Fat, 8.5% SNF.', 24, 25, 4, '500ml', 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=600&auto=format&fit=crop&q=80', 'Aisle 4', 'Dairy Section, Aisle 4 - Shelf A1 (Chilled)', '{"calories":58,"protein":"3.1g","fat":"3.0g","carbs":"4.7g","serving_size":"100ml"}'::jsonb, ARRAY['Milk', 'Toned Milk', 'Nandini', 'Dairy Essential']::text[], 4.9, 2400, FALSE),
('prod-amul-gold-milk', 'c1000000-0000-0000-0000-000000000001', 'Amul Gold Full Cream Milk 1L Tetra', 'Amul', 'Rich full cream pasteurised milk with 6.0% fat and 9.0% SNF. Excellent for making rich tea, coffee, and sweets.', 68, 72, 6, '1L', 'https://images.unsplash.com/photo-1563636619-e9143da7973b?w=600&auto=format&fit=crop&q=80', 'Aisle 4', 'Dairy Section, Aisle 4 - Shelf A1 (Chilled)', '{"calories":87,"protein":"3.5g","fat":"6.0g","carbs":"5.0g","serving_size":"100ml"}'::jsonb, ARRAY['Full Cream Milk', 'Amul Gold', 'Rich Dairy']::text[], 4.9, 1950, FALSE),
('prod-country-delight-milk', 'c1000000-0000-0000-0000-000000000001', 'Country Delight Pure Cow Milk 1L', 'Country Delight', 'Direct-from-farm 100% natural, unadulterated cow milk. Naturally sweet, tested for purity with zero chemical preservatives.', 85, 90, 6, '1L', 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=600&auto=format&fit=crop&q=80', 'Aisle 4', 'Dairy Section, Aisle 4 - Shelf A2 (Chilled)', '{"calories":62,"protein":"3.2g","fat":"3.5g","carbs":"4.6g","serving_size":"100ml"}'::jsonb, ARRAY['Organic Cow Milk', 'Pure Milk', 'Farm Fresh']::text[], 4.9, 1120, TRUE),
('prod-curd-milky-mist', 'c1000000-0000-0000-0000-000000000001', 'Milky Mist Farm Fresh Curd 1kg Tub', 'Milky Mist', 'Thick, creamy set curd prepared with whole cow milk and live lactic probiotic cultures.', 90, 100, 10, '1kg', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=600&auto=format&fit=crop&q=80', 'Aisle 4', 'Dairy Section, Aisle 4 - Shelf A2', '{"calories":65,"protein":"3.8g","fat":"3.5g","carbs":"4.5g","serving_size":"100g"}'::jsonb, ARRAY['Curd', 'Dahi', 'Probiotic', 'Thick Curd']::text[], 4.8, 1350, FALSE),
('prod-curd-mother-dairy', 'c1000000-0000-0000-0000-000000000001', 'Mother Dairy Classic Dahi 400g', 'Mother Dairy', 'Traditional home-style pasteurized dahi. Mildly sour and rich in probiotics for healthy digestion.', 35, 38, 8, '400g', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=600&auto=format&fit=crop&q=80', 'Aisle 4', 'Dairy Section, Aisle 4 - Shelf A2', '{"calories":60,"protein":"3.5g","fat":"3.0g","carbs":"4.6g","serving_size":"100g"}'::jsonb, ARRAY['Dahi', 'Curd', 'Probiotic']::text[], 4.6, 980, FALSE),
('prod-amul-vanilla', 'c1000000-0000-0000-0000-000000000001', 'Amul Vanilla Magic Real Milk Ice Cream 1L', 'Amul', 'Classic velvety vanilla ice cream prepared with pure buffalo and cow milk. 100% Real milk, no vegetable oil.', 140, 160, 12, '1L', 'https://images.unsplash.com/photo-1570197788417-0e82375c9371?w=600&auto=format&fit=crop&q=80', 'Aisle 4', 'Frozen Dessert Section, Aisle 4 - Freezer Unit 1', '{"calories":190,"protein":"3.6g","fat":"10.5g","carbs":"20.2g","serving_size":"100ml"}'::jsonb, ARRAY['Ice Cream', 'Vanilla', 'Real Milk Dessert']::text[], 4.8, 2200, FALSE),
('prod-cornetto-choco', 'c1000000-0000-0000-0000-000000000001', 'Kwality Walls Cornetto Double Chocolate 105ml', 'Kwality Wall''s', 'Crispy wafer cone filled with luscious chocolate dessert, topped with chocolate sauce and chocolate curls.', 45, 50, 10, '105ml', 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?w=600&auto=format&fit=crop&q=80', 'Aisle 4', 'Frozen Dessert Section, Aisle 4 - Freezer Unit 2', '{"calories":230,"protein":"3.0g","fat":"12g","carbs":"28g","serving_size":"105ml"}'::jsonb, ARRAY['Cornetto', 'Ice Cream Cone', 'Chocolate Dessert']::text[], 4.9, 1850, FALSE),
('prod-havmor-belgian', 'c1000000-0000-0000-0000-000000000001', 'Havmor Belgian Dark Chocolate Ice Cream 1L', 'Havmor', 'Intense dark chocolate ice cream loaded with Belgian chocolate chips and rich fudge swirls.', 220, 250, 12, '1L', 'https://images.unsplash.com/photo-1563805042-7684c019e1cb?w=600&auto=format&fit=crop&q=80', 'Aisle 4', 'Frozen Dessert Section, Aisle 4 - Freezer Unit 1', '{"calories":225,"protein":"4.2g","fat":"13.5g","carbs":"23g","serving_size":"100ml"}'::jsonb, ARRAY['Dark Chocolate', 'Belgian Chocolate', 'Ice Cream']::text[], 4.8, 1400, FALSE),
('prod-cadbury-silk', 'c1000000-0000-0000-0000-000000000005', 'Cadbury Dairy Milk Silk Chocolate Bar 150g', 'Cadbury', 'Smoother, creamier, and intensely chocolaty Dairy Milk Silk bar that melts in your mouth.', 175, 185, 5, '150g', 'https://images.unsplash.com/photo-1549007994-cb92caebd54b?w=600&auto=format&fit=crop&q=80', 'Aisle 5', 'Confectionery & Chocolates, Aisle 5 - Shelf B1', '{"calories":532,"protein":"7.8g","fat":"31g","carbs":"56g","serving_size":"100g"}'::jsonb, ARRAY['Chocolate', 'Cadbury Silk', 'Sweet Treat', 'Dairy Milk']::text[], 4.9, 4200, FALSE),
('prod-ferrero-rocher', 'c1000000-0000-0000-0000-000000000005', 'Ferrero Rocher Hazelnut Chocolates Box 16 Pcs (200g)', 'Ferrero Rocher', 'Whole crunchy hazelnut enveloped in smooth chocolate filling, encased in crispy wafer shell with milk chocolate and chopped hazelnuts.', 549, 599, 8, '200g', 'https://images.unsplash.com/photo-1541781774459-bb2af2f05b55?w=600&auto=format&fit=crop&q=80', 'Aisle 5', 'Confectionery & Chocolates, Aisle 5 - Shelf B2', '{"calories":603,"protein":"8.2g","fat":"42.7g","carbs":"44.4g","serving_size":"100g"}'::jsonb, ARRAY['Ferrero Rocher', 'Hazelnut Chocolate', 'Luxury Gifting']::text[], 5, 3100, FALSE),
('prod-kitkat-share', 'c1000000-0000-0000-0000-000000000005', 'Nestlé KitKat 4-Finger Share Pack 150g', 'Nestlé', 'Crispy wafer fingers covered with smooth milk chocolate. Have a break, have a KitKat.', 95, 105, 10, '150g', 'https://images.unsplash.com/photo-1621996346565-e3d5d6281096?w=600&auto=format&fit=crop&q=80', 'Aisle 5', 'Confectionery & Chocolates, Aisle 5 - Shelf B1', '{"calories":489,"protein":"6.4g","fat":"22.8g","carbs":"64.5g","serving_size":"100g"}'::jsonb, ARRAY['KitKat', 'Chocolate Wafer', 'Break Snack']::text[], 4.8, 2700, FALSE),
('prod-amul-dark-choco', 'c1000000-0000-0000-0000-000000000005', 'Amul Dark Chocolate 55% Cocoa 150g', 'Amul', 'Exquisite bittersweet dark chocolate crafted with fine cocoa and rich cocoa butter.', 110, 120, 8, '150g', 'https://images.unsplash.com/photo-1549007994-cb92caebd54b?w=600&auto=format&fit=crop&q=80', 'Aisle 5', 'Confectionery & Chocolates, Aisle 5 - Shelf B2', '{"calories":540,"protein":"5.2g","fat":"33g","carbs":"55g","serving_size":"100g"}'::jsonb, ARRAY['Dark Chocolate', '55% Cocoa', 'Healthy Chocolate', 'Antioxidants']::text[], 4.7, 1800, FALSE),
('prod-dark-fantasy', 'c1000000-0000-0000-0000-000000000005', 'Sunfeast Dark Fantasy Choco Fills 300g', 'Sunfeast', 'Crisp dark crust filled with molten flowing choco cream center. Irresistible gourmet cookie.', 120, 135, 11, '300g', 'https://images.unsplash.com/photo-1558961363-fa8fdf82db35?w=600&auto=format&fit=crop&q=80', 'Aisle 5', 'Biscuits & Cookies, Aisle 5 - Shelf A1', '{"calories":510,"protein":"5.0g","fat":"26g","carbs":"64g","serving_size":"100g"}'::jsonb, ARRAY['Dark Fantasy', 'Choco Fills', 'Cookies', 'Gourmet Biscuit']::text[], 4.9, 3600, FALSE),
('prod-mcvities-digestive', 'c1000000-0000-0000-0000-000000000005', 'McVitie''s Digestive Whole Wheat Biscuits 250g', 'McVitie''s', 'Traditional British digestive biscuits baked with wholesome wholewheat flour and dietary fiber.', 55, 60, 8, '250g', 'https://images.unsplash.com/photo-1590080875515-8a3a8dc5735e?w=600&auto=format&fit=crop&q=80', 'Aisle 5', 'Biscuits & Cookies, Aisle 5 - Shelf A2', '{"calories":471,"protein":"7.1g","fat":"20.6g","carbs":"62.2g","serving_size":"100g"}'::jsonb, ARRAY['Digestive Biscuits', 'Whole Wheat', 'High Fiber', 'Tea Time Snack']::text[], 4.8, 1450, FALSE)
